"use client"

import * as React from "react"

import {
  FileErrorBoundary,
  UnsupportedCard,
  ViewerFallback,
} from "./file-viewer-chrome"
import {
  descriptorResetKey,
  resolveFileDescriptor,
  type FileCategory,
  type FileDescriptor,
  type FileViewerProps,
} from "./file-viewer-core"
import { CsvDocViewer } from "./file-viewer-csv-viewer"
import { HtmlDocViewer } from "./file-viewer-html-viewer"
import { MarkdownDocViewer } from "./file-viewer-markdown-viewer"
import { TextDocViewer } from "./file-viewer-text-viewer"

export { type FileCategory, type FileViewerProps } from "./file-viewer-core"

const PdfViewer = React.lazy(() =>
  import("@/components/ui/pdf-viewer").then((m) => ({ default: m.PdfViewer }))
)
const DocxViewer = React.lazy(() =>
  import("@/components/ui/docx-viewer").then((m) => ({ default: m.DocxViewer }))
)
const ImageViewer = React.lazy(() =>
  import("@/components/ui/image-viewer").then((m) => ({
    default: m.ImageViewer,
  }))
)
const PptxViewer = React.lazy(() =>
  import("@/components/ui/pptx-viewer").then((m) => ({ default: m.PptxViewer }))
)
const XlsxViewer = React.lazy(() =>
  import("@/components/ui/xlsx-viewer").then((m) => ({ default: m.XlsxViewer }))
)
const TextViewer = React.lazy(() =>
  import("@/components/ui/text-viewer").then((m) => ({ default: m.TextViewer }))
)

function useIsClient() {
  return React.useSyncExternalStore(
    () => () => {},
    () => true,
    () => false
  )
}

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

function useDescriptorSignal(descriptorKey: string): AbortSignal {
  const controller = React.useMemo(() => {
    void descriptorKey
    return new AbortController()
  }, [descriptorKey])
  useIsomorphicLayoutEffect(() => {
    return () => controller.abort()
  }, [controller])
  return controller.signal
}

export function FileViewer(props: FileViewerProps) {
  const isClient = useIsClient()
  const descriptor = resolveFileDescriptor(props)
  const descriptorKey = descriptorResetKey(descriptor)
  const descriptorSignal = useDescriptorSignal(descriptorKey)
  const fallback = (
    <ViewerFallback
      category={descriptor.category}
      fileName={descriptor.downloadFileName}
      src={descriptor.loadUrl}
      className={props.className}
      bare={props.bare}
    />
  )

  if (!isClient) return fallback

  return (
    <FileErrorBoundary
      key={descriptorKey}
      descriptor={descriptor}
      className={props.className}
      resetKey={descriptorKey}
    >
      <React.Suspense fallback={fallback}>
        <FileViewerRoute
          {...props}
          descriptor={descriptor}
          descriptorSignal={descriptorSignal}
        />
      </React.Suspense>
    </FileErrorBoundary>
  )
}

function FileViewerRoute({
  descriptor,
  className,
  bare = false,
  isolateStyles = false,
  descriptorSignal,
}: FileViewerProps & {
  descriptor: FileDescriptor
  descriptorSignal: AbortSignal
}) {
  const { category, downloadFileName, loadUrl } = descriptor
  if (descriptor.source.kind === "text") {
    if (category === "text") {
      return (
        <TextViewer
          source={descriptor.source}
          className={className}
          bare={bare}
        />
      )
    }
    return (
      <UnsupportedCard
        fileName={downloadFileName}
        className={className}
        bare={bare}
      />
    )
  }

  if (!loadUrl) {
    return (
      <UnsupportedCard
        fileName={downloadFileName}
        downloadHref={descriptor.downloadHref}
        className={className}
        bare={bare}
      />
    )
  }

  switch (category) {
    case "pdf":
      return (
        <PdfViewer
          src={loadUrl}
          className={className}
          bare={bare}
          downloadFileName={downloadFileName}
        />
      )
    case "docx":
      return <DocxViewer src={loadUrl} className={className} bare={bare} />
    case "image":
      return (
        <ImageViewer
          src={loadUrl}
          className={className}
          bare={bare}
          downloadFileName={downloadFileName}
        />
      )
    case "pptx":
      return (
        <PptxViewer
          src={loadUrl}
          className={className}
          bare={bare}
          downloadFileName={downloadFileName}
        />
      )
    case "xlsx":
      return (
        <XlsxViewer
          src={loadUrl}
          className={className}
          bare={bare}
          downloadFileName={downloadFileName}
          isolateStyles={isolateStyles}
        />
      )
    case "csv":
      return (
        <CsvDocViewer
          src={loadUrl}
          fileName={downloadFileName}
          mimeType={descriptor.mimeType}
          className={className}
          bare={bare}
          isolateStyles={isolateStyles}
        />
      )
    case "markdown":
      return (
        <MarkdownDocViewer
          src={loadUrl}
          fileName={downloadFileName}
          className={className}
          bare={bare}
          descriptorSignal={descriptorSignal}
        />
      )
    case "html":
      return (
        <HtmlDocViewer
          src={loadUrl}
          fileName={downloadFileName}
          className={className}
          bare={bare}
          descriptorSignal={descriptorSignal}
        />
      )
    case "text":
      return (
        <TextDocViewer
          src={loadUrl}
          fileName={downloadFileName}
          className={className}
          bare={bare}
          isolateStyles={isolateStyles}
          descriptorSignal={descriptorSignal}
        />
      )
    default:
      return (
        <UnsupportedCard
          src={loadUrl}
          fileName={downloadFileName}
          className={className}
          bare={bare}
        />
      )
  }
}

import {
  detectCategory,
  extensionOf,
  extractName,
  resolveViewerDescriptor,
  type FileCategory,
  type ViewerDescriptor,
  type ViewerSource,
} from "@/lib/viewer-source"

export type { FileCategory, ViewerSource }

export interface FileViewerProps {
  source: ViewerSource
  as?: FileCategory
  className?: string
  bare?: boolean
  isolateStyles?: boolean
}

export type FileDescriptor = ViewerDescriptor

export function resolveFileDescriptor({
  source,
  as,
}: FileViewerProps): FileDescriptor {
  return resolveViewerDescriptor({
    source,
    category: as,
  })
}

export function descriptorResetKey(descriptor: FileDescriptor): string {
  return [
    descriptor.identityKey,
    descriptor.displayName,
    descriptor.mimeType ?? "",
    descriptor.category,
  ].join("\u0000")
}

export { detectCategory, extensionOf, extractName }

export async function timed<T>(
  label: string,
  fn: () => Promise<T>
): Promise<T> {
  const on =
    typeof globalThis !== "undefined" &&
    (globalThis as { __FILE_VIEWER_PROFILE__?: boolean })
      .__FILE_VIEWER_PROFILE__
  if (!on) return fn()
  const t0 = performance.now()
  try {
    return await fn()
  } finally {
    console.log(
      `[file-viewer] ${label} ${(performance.now() - t0).toFixed(1)}ms`
    )
  }
}

export function baseName(src: string): string {
  return src.split("/").pop() ?? src
}

"use client"

import * as React from "react"
import { Download, Maximize, Minus, Plus } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import { Skeleton } from "@/components/ui/skeleton"

import type { FileCategory, FileDescriptor } from "./file-viewer-core"

const TEXT_SKELETON_FONT = 12.5
const TEXT_SKELETON_LINE_HEIGHT = 20

export function DocShell({
  fileName,
  src,
  meta,
  actions,
  className,
  bare,
  children,
}: {
  fileName: string
  src: string
  meta?: string
  actions?: React.ReactNode
  className?: string
  bare?: boolean
  children: React.ReactNode
}) {
  return (
    <div
      data-slot="file-viewer"
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-card" : "rounded-xl border bg-muted/30",
        className
      )}
    >
      <div className="flex h-10 min-w-0 flex-shrink-0 items-center gap-1 border-b bg-card px-2">
        <span
          className="min-w-0 flex-1 truncate px-1 text-xs font-medium"
          title={fileName}
        >
          {fileName}
        </span>
        {meta ? (
          <span className="max-w-[45%] min-w-0 flex-shrink truncate text-xs text-muted-foreground tabular-nums">
            {meta}
          </span>
        ) : null}
        <div className="ml-auto flex shrink-0 items-center gap-1">
          {actions}
          {actions ? (
            <Separator orientation="vertical" className="mx-1 h-4" />
          ) : null}
          <Button
            variant="ghost"
            size="icon-sm"
            className="size-7"
            aria-label="Download"
            title="Download"
            render={
              <a
                href={src}
                download={fileName}
                target="_blank"
                rel="noreferrer"
              />
            }
          >
            <Download />
          </Button>
        </div>
      </div>
      <div className="flex min-h-0 flex-1 flex-col">{children}</div>
    </div>
  )
}

function IconButton({
  label,
  children,
  ...props
}: React.ComponentProps<typeof Button> & { label: string }) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="size-7"
      aria-label={label}
      title={label}
      {...props}
    >
      {children}
    </Button>
  )
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

export function useZoom() {
  const [scale, setScale] = React.useState(1)
  const zoom = React.useCallback(
    (factor: number) => setScale((s) => clamp(s * factor, 0.25, 5)),
    []
  )
  const reset = React.useCallback(() => setScale(1), [])
  return { scale, zoom, reset }
}

export function ZoomActions({
  scale,
  zoom,
  reset,
}: {
  scale: number
  zoom: (factor: number) => void
  reset: () => void
}) {
  return (
    <>
      <IconButton label="Zoom out" onClick={() => zoom(1 / 1.2)}>
        <Minus />
      </IconButton>
      <span className="w-12 text-center text-xs text-muted-foreground tabular-nums">
        {Math.round(scale * 100)}%
      </span>
      <IconButton label="Zoom in" onClick={() => zoom(1.2)}>
        <Plus />
      </IconButton>
      <IconButton label="Actual size" onClick={reset}>
        <Maximize />
      </IconButton>
    </>
  )
}

export function ZoomActionsSkeleton() {
  const inert = { disabled: true, tabIndex: -1, "aria-hidden": true } as const
  return (
    <>
      <IconButton label="Zoom out" {...inert}>
        <Minus />
      </IconButton>
      <span className="w-12 text-center text-xs text-muted-foreground tabular-nums">
        100%
      </span>
      <IconButton label="Zoom in" {...inert}>
        <Plus />
      </IconButton>
      <IconButton label="Actual size" {...inert}>
        <Maximize />
      </IconButton>
    </>
  )
}

export function UnsupportedCard({
  src,
  downloadHref,
  fileName,
  className,
  bare,
  message = "No preview for",
}: {
  src?: string
  downloadHref?: string
  fileName: string
  className?: string
  bare?: boolean
  message?: string
}) {
  const href = downloadHref ?? src
  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center gap-3 p-8 text-center",
        bare ? "h-full bg-muted/20" : "min-h-64 rounded-xl border bg-muted/30",
        className
      )}
      data-slot="file-viewer"
    >
      <p className="text-sm text-muted-foreground">
        {message}{" "}
        <span className="font-medium text-foreground">{fileName}</span>.
      </p>
      {href ? (
        <Button
          variant="outline"
          size="sm"
          render={
            <a
              href={href}
              download={fileName}
              target="_blank"
              rel="noreferrer"
            />
          }
        >
          <Download className="mr-1.5 size-4" />
          Download
        </Button>
      ) : null}
    </div>
  )
}

export function ViewerFallback({
  category,
  fileName,
  src,
  className,
  bare = false,
}: {
  category?: FileCategory
  fileName?: string
  src?: string
  className?: string
  bare?: boolean
}) {
  if (
    src != null &&
    fileName != null &&
    (category === "text" ||
      category === "markdown" ||
      category === "html" ||
      category === "csv")
  ) {
    return (
      <DocShell
        fileName={fileName}
        src={src}
        className={className}
        bare={bare}
        actions={<ZoomActionsSkeleton />}
      >
        {category === "csv" ? (
          <TableBodySkeleton />
        ) : category === "text" ? (
          <TextBodySkeleton />
        ) : (
          <div className="min-h-0 flex-1 bg-card p-4">
            <Skeleton className="size-full rounded-md" />
          </div>
        )}
      </DocShell>
    )
  }

  const tabular = category === "xlsx"
  const pageAspect =
    category === "pptx" || category === "image" ? "4 / 3" : "8.5 / 11"

  return (
    <div
      data-slot="file-viewer"
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
    >
      <div className="flex h-10 min-w-0 flex-shrink-0 items-center gap-1 border-b bg-card px-2">
        <span className="min-w-0 flex-1 px-1">
          <Skeleton className="inline-block h-3 w-16 align-middle" />
        </span>
        <div className="ml-auto flex shrink-0 items-center gap-1">
          {category !== "unsupported" ? (
            <>
              <ZoomActionsSkeleton />
              <Separator orientation="vertical" className="mx-1 h-4" />
            </>
          ) : null}
          <Button
            variant="ghost"
            size="icon-sm"
            className="size-7"
            disabled
            tabIndex={-1}
            aria-hidden
          >
            <Download />
          </Button>
        </div>
      </div>
      {tabular ? (
        <TableBodySkeleton />
      ) : (
        <div className="min-h-0 flex-1 overflow-hidden">
          <div className="flex flex-col items-center p-4">
            <Skeleton
              aria-hidden
              className="w-full rounded-md"
              style={{ aspectRatio: pageAspect }}
            />
          </div>
        </div>
      )}
    </div>
  )
}

