export class FileErrorBoundary extends React.Component<
  {
    children: React.ReactNode
    descriptor: FileDescriptor
    className?: string
    resetKey?: unknown
  },
  { error: boolean }
> {
  state = { error: false }

  componentDidUpdate(prev: { resetKey?: unknown }) {
    if (prev.resetKey !== this.props.resetKey && this.state.error) {
      this.setState({ error: false })
    }
  }

  static getDerivedStateFromError() {
    return { error: true }
  }

  render() {
    if (this.state.error) {
      return (
        <UnsupportedCard
          src={this.props.descriptor.loadUrl}
          downloadHref={this.props.descriptor.downloadHref}
          fileName={this.props.descriptor.downloadFileName}
          className={this.props.className}
          message="Could not load"
        />
      )
    }
    return this.props.children
  }
}

export interface SharedAbortableRequest<T> {
  controller: AbortController
  promise: Promise<T>
  subscriberPromises: WeakMap<AbortSignal, Promise<T>>
  subscribers: Set<AbortSignal>
  settled: boolean
}

export function abortError(): DOMException {
  return new DOMException("Aborted", "AbortError")
}

export function isAbortError(error: unknown): boolean {
  return (
    (error instanceof DOMException && error.name === "AbortError") ||
    (error instanceof Error && error.name === "AbortError")
  )
}

export function promiseForSignal<T>(
  map: WeakMap<AbortSignal, Promise<T>>,
  signal: AbortSignal,
  create: () => Promise<T>
): Promise<T> {
  if (signal.aborted) return Promise.reject(abortError())

  const existingPromise = map.get(signal)
  if (existingPromise) return existingPromise

  const promise = create().catch((error: unknown) => {
    map.delete(signal)
    throw error
  })
  map.set(signal, promise)
  return promise
}

export function subscribeToAbortableRequest<T>(
  entry: SharedAbortableRequest<T>,
  signal: AbortSignal,
  onNoSubscribers: () => void
): Promise<T> {
  return promiseForSignal(entry.subscriberPromises, signal, () => {
    entry.subscribers.add(signal)

    return new Promise<T>((resolve, reject) => {
      let done = false

      const cleanup = () => {
        signal.removeEventListener("abort", onAbort)
        entry.subscribers.delete(signal)
      }

      const onAbort = () => {
        if (done) return
        done = true
        cleanup()
        if (!entry.settled && entry.subscribers.size === 0) {
          entry.controller.abort()
          onNoSubscribers()
        }
        reject(abortError())
      }

      signal.addEventListener("abort", onAbort, { once: true })

      entry.promise.then(
        (value) => {
          if (done) return
          done = true
          cleanup()
          resolve(value)
        },
        (error: unknown) => {
          if (done) return
          done = true
          cleanup()
          reject(error)
        }
      )
    })
  })
}

export const RESOURCE_CACHE_MAX = 12

export function lruGet<K, V>(map: Map<K, V>, key: K): V | undefined {
  const v = map.get(key)
  if (v !== undefined) {
    map.delete(key)
    map.set(key, v)
  }
  return v
}

export function lruSet<K, V>(
  map: Map<K, V>,
  key: K,
  value: V,
  onEvict?: (key: K, value: V) => void,
  max = RESOURCE_CACHE_MAX
) {
  map.delete(key)
  map.set(key, value)
  while (map.size > max) {
    const oldest = map.keys().next().value as K
    const dropped = map.get(oldest) as V
    map.delete(oldest)
    onEvict?.(oldest, dropped)
  }
}

export function cachedPromise<K, V>(
  map: Map<K, Promise<V>>,
  key: K,
  create: () => Promise<V>,
  {
    max = RESOURCE_CACHE_MAX,
    onEvict,
    onReject,
  }: {
    max?: number
    onEvict?: (key: K, value: Promise<V>) => void
    onReject?: (key: K, error: unknown) => void
  } = {}
): Promise<V> {
  let promise = lruGet(map, key)
  if (!promise) {
    promise = create().catch((error: unknown) => {
      map.delete(key)
      onReject?.(key, error)
      throw error
    })
    lruSet(map, key, promise, onEvict, max)
  }
  return promise
}

import {
  isAbortError,
  subscribeToAbortableRequest,
  type SharedAbortableRequest,
} from "./file-viewer-async"
import { baseName, timed } from "./file-viewer-core"
import { cachedPromise, lruGet, lruSet } from "./file-viewer-resource-cache"

export interface TextResourceSubscription {
  src: string
  signal: AbortSignal
}

export interface TextResourceCache {
  load(sub: TextResourceSubscription): Promise<string>
  clear(): void
  size(): number
}

export function createTextResourceCache(maxEntries = 12): TextResourceCache {
  const requests = new Map<string, SharedAbortableRequest<string>>()
  const promises = new Map<string, Promise<string>>()

  function remove(src: string) {
    requests.delete(src)
    promises.delete(src)
  }

  function entryFor(src: string): SharedAbortableRequest<string> {
    const existingEntry = lruGet(requests, src)
    if (existingEntry) {
      lruGet(promises, src)
      return existingEntry
    }

    const controller = new AbortController()
    let entry: SharedAbortableRequest<string> | null = null
    const promise = cachedPromise(
      promises,
      src,
      () =>
        timed(`text:fetch ${baseName(src)}`, () =>
          fetch(src, { signal: controller.signal }).then((response) => {
            if (!response.ok)
              throw new Error(`Failed to load file: ${response.status}`)
            return response.text()
          })
        ),
      {
        max: maxEntries,
        onEvict(key) {
          requests.get(key)?.controller.abort()
          requests.delete(key)
        },
        onReject(key, error) {
          if (!isAbortError(error)) requests.delete(key)
        },
      }
    ).finally(() => {
      if (entry) entry.settled = true
    })

    entry = {
      controller,
      promise,
      subscriberPromises: new WeakMap(),
      subscribers: new Set(),
      settled: false,
    }

    lruSet(
      requests,
      src,
      entry,
      (key, dropped) => {
        dropped.controller.abort()
        promises.delete(key)
      },
      maxEntries
    )
    return entry
  }

  return {
    load(sub) {
      const entry = entryFor(sub.src)
      return subscribeToAbortableRequest(entry, sub.signal, () =>
        remove(sub.src)
      )
    },
    clear() {
      for (const entry of requests.values()) entry.controller.abort()
      requests.clear()
      promises.clear()
    },
    size() {
      return requests.size
    },
  }
}

export const textResource = createTextResourceCache()

export function loadTextResource(
  sub: TextResourceSubscription
): Promise<string> {
  return textResource.load(sub)
}

import {
  isAbortError,
  subscribeToAbortableRequest,
  type SharedAbortableRequest,
} from "./file-viewer-async"
import { baseName, timed } from "./file-viewer-core"
import { lruGet, lruSet } from "./file-viewer-resource-cache"

const TEXT_PAGE_BYTES = 512 * 1024

export interface TextSnapshot {
  text: string
  bytesLoaded: number
  totalBytes: number | null
  done: boolean
}

interface TextLoaderState extends TextSnapshot {
  decoder: TextDecoder
}

export type TextLoadMode = "stream" | "full"

export interface TextSubscription {
  textKey: string
  src: string
  mode: TextLoadMode
  signal: AbortSignal
}

export interface TextLoader {
  snapshot(textKey: string): TextSnapshot | null
  loadFirstChunk(sub: TextSubscription): Promise<TextSnapshot>
  loadNextChunk(sub: TextSubscription): Promise<TextSnapshot>
  release(textKey: string): void
  clear(): void
  size(): number
}

interface RangeResult {
  buf: ArrayBuffer
  whole: boolean
  total: number | null
}

export function textKeyForFile(src: string, mode: TextLoadMode): string {
  return `${mode}\u0000${src}`
}

export function isSameTextView(
  currentTextViewKey: string,
  startedTextViewKey: string
): boolean {
  return currentTextViewKey === startedTextViewKey
}

function snapshotOf(loader: TextLoaderState): TextSnapshot {
  return {
    text: loader.text,
    bytesLoaded: loader.bytesLoaded,
    totalBytes: loader.totalBytes,
    done: loader.done,
  }
}

async function fetchRange(
  src: string,
  start: number,
  end: number,
  signal: AbortSignal
): Promise<RangeResult> {
  const res = await fetch(src, {
    headers: { Range: `bytes=${start}-${end}` },
    signal,
  })
  if (res.status === 416)
    return { buf: new ArrayBuffer(0), whole: false, total: null }
  if (!res.ok) throw new Error(`Failed to load file: ${res.status}`)
  const buf = await res.arrayBuffer()
  let total: number | null = null
  const contentRange = res.headers.get("content-range")
  if (contentRange) {
    const m = contentRange.match(/\/(\d+)\s*$/)
    if (m) total = Number(m[1])
  } else {
    const len = Number(res.headers.get("content-length"))
    if (Number.isFinite(len) && len > 0) total = len
  }
  return { buf, whole: res.status === 200, total }
}

export function createTextLoader(maxEntries = 12): TextLoader {
  const firstRequests = new Map<string, SharedAbortableRequest<TextSnapshot>>()
  const nextRequests = new Map<string, SharedAbortableRequest<TextSnapshot>>()
  const loaders = new Map<string, TextLoaderState>()

  function remove(textKey: string) {
    firstRequests.delete(textKey)
    nextRequests.delete(textKey)
    loaders.delete(textKey)
  }

  function firstEntry(
    sub: TextSubscription
  ): SharedAbortableRequest<TextSnapshot> {
    let entry = lruGet(firstRequests, sub.textKey)
    if (entry) return entry

    const controller = new AbortController()
    entry = {
      controller,
      subscriberPromises: new WeakMap(),
      subscribers: new Set(),
      settled: false,
      promise: timed(`text:first-chunk ${baseName(sub.src)}`, async () => {
        const decoder = new TextDecoder()
        if (sub.mode === "full") {
          const res = await fetch(sub.src, { signal: controller.signal })
          if (!res.ok) throw new Error(`Failed to load file: ${res.status}`)
          const buf = await res.arrayBuffer()
          const text = decoder.decode(buf)
          const bytesLoaded = buf.byteLength
          const loader: TextLoaderState = {
            text,
            bytesLoaded,
            totalBytes: bytesLoaded,
            done: true,
            decoder,
          }
          loaders.set(sub.textKey, loader)
          return snapshotOf(loader)
        }

        const { buf, whole, total } = await fetchRange(
          sub.src,
          0,
          TEXT_PAGE_BYTES - 1,
          controller.signal
        )
        const text = decoder.decode(buf, { stream: !whole })
        const bytesLoaded = buf.byteLength
        const done =
          whole ||
          buf.byteLength < TEXT_PAGE_BYTES ||
          (total != null && bytesLoaded >= total)
        const loader: TextLoaderState = {
          text: done && !whole ? text + decoder.decode() : text,
          bytesLoaded,
          totalBytes: whole ? bytesLoaded : total,
          done,
          decoder,
        }
        loaders.set(sub.textKey, loader)
        return snapshotOf(loader)
      })
        .catch((error: unknown) => {
          remove(sub.textKey)
          throw error
        })
        .finally(() => {
          if (entry) entry.settled = true
        }),
    }

    lruSet(
      firstRequests,
      sub.textKey,
      entry,
      (textKey, dropped) => {
        dropped.controller.abort()
        loaders.delete(textKey)
        nextRequests.delete(textKey)
      },
      maxEntries
    )
    return entry
  }

  function nextEntry(
    sub: TextSubscription
  ): SharedAbortableRequest<TextSnapshot> {
    let entry = nextRequests.get(sub.textKey)
    if (entry) return entry

    const loader = loaders.get(sub.textKey)
    const controller = new AbortController()
    entry = {
      controller,
      subscriberPromises: new WeakMap(),
      subscribers: new Set(),
      settled: false,
      promise: (async () => {
        if (!loader || loader.done) {
          return loader
            ? snapshotOf(loader)
            : { text: "", bytesLoaded: 0, totalBytes: null, done: true }
        }

        const start = loader.bytesLoaded
        const { buf, total } = await fetchRange(
          sub.src,
          start,
          start + TEXT_PAGE_BYTES - 1,
          controller.signal
        )
        loader.bytesLoaded += buf.byteLength
        if (total != null) loader.totalBytes = total
        const reachedEnd =
          buf.byteLength === 0 ||
          buf.byteLength < TEXT_PAGE_BYTES ||
          (loader.totalBytes != null && loader.bytesLoaded >= loader.totalBytes)
        loader.text += loader.decoder.decode(buf, { stream: !reachedEnd })
        if (reachedEnd) loader.done = true
        return snapshotOf(loader)
      })()
        .catch((error: unknown) => {
          if (!isAbortError(error)) nextRequests.delete(sub.textKey)
          throw error
        })
        .finally(() => {
          if (entry) entry.settled = true
          nextRequests.delete(sub.textKey)
        }),
    }

    nextRequests.set(sub.textKey, entry)
    return entry
  }

  return {
    snapshot(textKey) {
      const loader = loaders.get(textKey)
      return loader ? snapshotOf(loader) : null
    },
    loadFirstChunk(sub) {
      const entry = firstEntry(sub)
      return subscribeToAbortableRequest(entry, sub.signal, () =>
        remove(sub.textKey)
      )
    },
    loadNextChunk(sub) {
      const entry = nextEntry(sub)
      return subscribeToAbortableRequest(entry, sub.signal, () => {
        nextRequests.delete(sub.textKey)
      })
    },
    release: remove,
    clear() {
      for (const entry of firstRequests.values()) entry.controller.abort()
      for (const entry of nextRequests.values()) entry.controller.abort()
      firstRequests.clear()
      nextRequests.clear()
      loaders.clear()
    },
    size() {
      return firstRequests.size
    },
  }
}

export const textLoader = createTextLoader()

export function loadFirstTextChunk(
  sub: TextSubscription
): Promise<TextSnapshot> {
  return textLoader.loadFirstChunk(sub)
}

export function loadNextTextChunk(
  sub: TextSubscription
): Promise<TextSnapshot> {
  return textLoader.loadNextChunk(sub)
}

export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

"use client"

import * as React from "react"
import { useVirtualizer } from "@tanstack/react-virtual"
import Prism from "prismjs"
import { createPortal } from "react-dom"

import { isAbortError } from "./file-viewer-async"
import { DocShell, useZoom, ZoomActions } from "./file-viewer-chrome"
import {
  formatBytes,
  isSameTextView,
  loadFirstTextChunk,
  loadNextTextChunk,
  textKeyForFile,
  textLoader,
  type TextLoadMode,
  type TextSnapshot,
} from "./file-viewer-text-loader"

const TEXT_FONT = 12.5
const TEXT_LINE_HEIGHT = 20
const TEXT_CHAR_WIDTH = TEXT_FONT * 0.6
const TEXT_LOAD_AHEAD_PX = 600
const JSON_LINE_MAX = 2000

Prism.manual = true

const JSON_GRAMMAR: Prism.Grammar = {
  property: {
    pattern: /"(?:\\.|[^\\"\r\n])*"(?=\s*:)/,
    greedy: true,
  },
  string: {
    pattern: /"(?:\\.|[^\\"\r\n])*"(?!\s*:)/,
    greedy: true,
  },
  number: /-?\b\d+(?:\.\d+)?(?:[eE][+-]?\d+)?\b/,
  punctuation: /[{}[\],]/,
  operator: /:/,
  boolean: /\b(?:false|true)\b/,
  null: { pattern: /\bnull\b/, alias: "keyword" },
}

function highlightGrammar(fileName: string): Prism.Grammar | null {
  return /\.(json|json5)$/i.test(fileName) ? JSON_GRAMMAR : null
}

interface Leaf {
  type: string
  text: string
}

function flattenTokens(
  tokens: (string | Prism.Token)[],
  parentType = "",
  out: Leaf[] = []
): Leaf[] {
  for (const tok of tokens) {
    if (typeof tok === "string") {
      out.push({ type: parentType, text: tok })
    } else if (Array.isArray(tok.content)) {
      flattenTokens(tok.content as (string | Prism.Token)[], tok.type, out)
    } else if (typeof tok.content === "string") {
      out.push({ type: tok.type, text: tok.content })
    } else {
      flattenTokens([tok.content as Prism.Token], tok.type, out)
    }
  }
  return out
}

const TOKEN_CLASS: Record<string, string> = {
  property: "fv-tok-key",
  string: "fv-tok-string",
  number: "fv-tok-number",
  boolean: "fv-tok-keyword",
  null: "fv-tok-keyword",
  keyword: "fv-tok-keyword",
  punctuation: "fv-tok-punct",
  operator: "fv-tok-punct",
}

const SYNTAX_STYLE = `
.fv-tok-key { color: var(--fv-syntax-key, #0550ae); }
.fv-tok-string { color: var(--fv-syntax-string, #0a7d33); }
.fv-tok-number { color: var(--fv-syntax-number, #b5690c); }
.fv-tok-keyword { color: var(--fv-syntax-keyword, #8250df); }
.fv-tok-punct { color: var(--fv-syntax-punct, color-mix(in oklab, var(--foreground) 55%, transparent)); }
.dark .fv-tok-key { color: var(--fv-syntax-key, #6cb6ff); }
.dark .fv-tok-string { color: var(--fv-syntax-string, #8ddb8c); }
.dark .fv-tok-number { color: var(--fv-syntax-number, #e3b341); }
.dark .fv-tok-keyword { color: var(--fv-syntax-keyword, #dcbdfb); }
`

function LineContent({
  line,
  leaves,
}: {
  line: string
  leaves: Leaf[] | null
}) {
  if (line === "") return <> </>
  if (!leaves) return <>{line}</>
  return (
    <>
      {leaves.map((leaf, i) =>
        leaf.type && TOKEN_CLASS[leaf.type] ? (
          <span key={i} className={TOKEN_CLASS[leaf.type]}>
            {leaf.text}
          </span>
        ) : (
          <React.Fragment key={i}>{leaf.text}</React.Fragment>
        )
      )}
    </>
  )
}

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

function stripHasRules(owner: CSSStyleSheet | CSSGroupingRule) {
  const rules = owner.cssRules
  if (!rules) return
  for (let i = rules.length - 1; i >= 0; i--) {
    const r = rules[i]
    if ((r as CSSStyleRule).selectorText?.includes(":has(")) {
      try {
        owner.deleteRule(i)
      } catch {
        // ignore a rule that cannot be removed
      }
    } else if ((r as CSSGroupingRule).cssRules?.length) {
      stripHasRules(r as CSSGroupingRule)
    }
  }
}

let sharedSheets: CSSStyleSheet[] | null = null
function getSharedSheets(): CSSStyleSheet[] {
  if (sharedSheets) return sharedSheets
  const out: CSSStyleSheet[] = []
  for (const ss of Array.from(document.styleSheets)) {
    let rules: CSSRuleList
    try {
      rules = ss.cssRules
    } catch {
      continue
    }
    let text = ""
    for (const rule of Array.from(rules)) text += rule.cssText + "\n"
    try {
      const sheet = new CSSStyleSheet()
      sheet.replaceSync(text)
      stripHasRules(sheet)
      out.push(sheet)
    } catch {
      // skip sheets that cannot be reconstructed
    }
  }
  sharedSheets = out
  return out
}

function ShadowScope({
  className,
  style,
  children,
}: {
  className?: string
  style?: React.CSSProperties
  children: React.ReactNode
}) {
  const hostRef = React.useRef<HTMLDivElement>(null)
  const [root, setRoot] = React.useState<ShadowRoot | null>(null)

  useIsomorphicLayoutEffect(() => {
    const host = hostRef.current
    if (!host) return
    const sr = host.shadowRoot ?? host.attachShadow({ mode: "open" })
    try {
      sr.adoptedStyleSheets = getSharedSheets()
    } catch {
      for (const node of Array.from(
        document.querySelectorAll('style, link[rel="stylesheet"]')
      )) {
        try {
          sr.appendChild(node.cloneNode(true))
        } catch {
          // ignore nodes that cannot be cloned
        }
      }
    }
    setRoot(sr)
  }, [])

  return (
    <div ref={hostRef} className={className} style={style}>
      {root ? createPortal(children, root) : null}
    </div>
  )
}

function ScrollerShell({
  isolate,
  className,
  style,
  children,
}: {
  isolate: boolean
  className?: string
  style?: React.CSSProperties
  children: React.ReactNode
}) {
  if (isolate) {
    return (
      <ShadowScope className={className} style={style}>
        {children}
      </ShadowScope>
    )
  }
  return (
    <div className={className} style={style}>
      {children}
    </div>
  )
}

function makeTextSubscription(
  src: string,
  mode: TextLoadMode,
  signal: AbortSignal
) {
  return {
    textKey: textKeyForFile(src, mode),
    src,
    mode,
    signal,
  }
}

export function TextDocViewer({
  src,
  fileName,
  className,
  bare,
  isolateStyles,
  descriptorSignal,
}: {
  src: string
  fileName: string
  className?: string
  bare?: boolean
  isolateStyles?: boolean
  descriptorSignal: AbortSignal
}) {
  const isJson = /\.(json|json5)$/i.test(fileName)
  const textMode: TextLoadMode = isJson ? "full" : "stream"
  const textKey = textKeyForFile(src, textMode)
  const textViewKey = `${textKey}\u0000${fileName}`
  const currentTextViewKeyRef = React.useRef(textViewKey)
  currentTextViewKeyRef.current = textViewKey

  const [snap, setSnap] = React.useState<TextSnapshot | null>(() =>
    textLoader.snapshot(textKey)
  )
  const [loadingMore, setLoadingMore] = React.useState(false)
  const [loadError, setLoadError] = React.useState<Error | null>(null)
  const [renderedTextViewKey, setRenderedTextViewKey] =
    React.useState(textViewKey)
  const grammar = React.useMemo(() => highlightGrammar(fileName), [fileName])
  const tokenCacheRef = React.useRef<Map<string, Leaf[]>>(new Map())

  if (renderedTextViewKey !== textViewKey) {
    setRenderedTextViewKey(textViewKey)
    setSnap(textLoader.snapshot(textKey))
    setLoadingMore(false)
    setLoadError(null)
    tokenCacheRef.current = new Map()
  }
  if (loadError) throw loadError

  React.useEffect(() => {
    const startedTextViewKey = textViewKey
    const sub = makeTextSubscription(src, textMode, descriptorSignal)
    void loadFirstTextChunk(sub)
      .then((next) => {
        if (!isSameTextView(currentTextViewKeyRef.current, startedTextViewKey))
          return
        setSnap(next)
      })
      .catch((error: unknown) => {
        if (!isSameTextView(currentTextViewKeyRef.current, startedTextViewKey))
          return
        if (isAbortError(error)) return
        setLoadError(error instanceof Error ? error : new Error(String(error)))
      })
  }, [descriptorSignal, src, textKey, textMode, textViewKey])

  const lineLeaves = React.useCallback(
    (line: string): Leaf[] | null => {
      if (!grammar || line.length === 0 || line.length > JSON_LINE_MAX)
        return null
      const cache = tokenCacheRef.current
      let leaves = cache.get(line)
      if (!leaves) {
        leaves = flattenTokens(Prism.tokenize(line, grammar))
        cache.set(line, leaves)
      }
      return leaves
    },
    [grammar]
  )

  const loadMore = React.useCallback(() => {
    const startedTextViewKey = textViewKey
    const sub = makeTextSubscription(src, textMode, descriptorSignal)
    setLoadingMore((busy) => {
      if (busy) return busy
      void loadNextTextChunk(sub)
        .then((next) => {
          if (
            !isSameTextView(currentTextViewKeyRef.current, startedTextViewKey)
          )
            return
          setSnap(next)
          setLoadingMore(false)
        })
        .catch((error: unknown) => {
          if (
            !isSameTextView(currentTextViewKeyRef.current, startedTextViewKey)
          )
            return
          if (isAbortError(error)) {
            setLoadingMore(false)
            return
          }
          setLoadError(
            error instanceof Error ? error : new Error(String(error))
          )
          setLoadingMore(false)
        })
      return true
    })
  }, [descriptorSignal, src, textMode, textViewKey])

  const text = React.useMemo(() => {
    if (!snap) return ""
    if (isJson && snap.done) {
      try {
        return JSON.stringify(JSON.parse(snap.text), null, 2)
      } catch {
        // invalid JSON renders as the original text
      }
    }
    return snap.text
  }, [snap, isJson])

  const lines = React.useMemo(() => text.replace(/\n$/, "").split("\n"), [text])
  const maxChars = React.useMemo(
    () => lines.reduce((m, l) => Math.max(m, l.length), 0),
    [lines]
  )

  const { scale, zoom, reset } = useZoom()
  const fontSize = TEXT_FONT * scale
  const lineHeight = Math.round(TEXT_LINE_HEIGHT * scale)
  const charWidth = TEXT_CHAR_WIDTH * scale

  const scrollRef = React.useRef<HTMLDivElement>(null)
  const virtualizer = useVirtualizer({
    count: lines.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => lineHeight,
    overscan: 16,
  })

  React.useLayoutEffect(() => {
    virtualizer.measure()
  }, [lineHeight, virtualizer])

  const handleScroll = React.useCallback(
    (e: React.UIEvent<HTMLDivElement>) => {
      if (!snap || snap.done || loadingMore) return
      const el = e.currentTarget
      if (
        el.scrollHeight - el.scrollTop - el.clientHeight <
        TEXT_LOAD_AHEAD_PX
      ) {
        loadMore()
      }
    },
    [snap, loadingMore, loadMore]
  )

  const digits = String(Math.max(lines.length, 1)).length
  const gutterWidth = Math.round(Math.max(40, 12 + digits * 8) * scale)
  const contentWidth = Math.ceil(maxChars * charWidth) + 24
  const totalWidth = gutterWidth + contentWidth

  const meta = !snap
    ? "Loading"
    : snap.done
      ? `${lines.length.toLocaleString()} line${lines.length === 1 ? "" : "s"}`
      : `${lines.length.toLocaleString()} lines · ${formatBytes(snap.bytesLoaded)}${
          snap.totalBytes ? ` / ${formatBytes(snap.totalBytes)}` : ""
        } loaded`

  return (
    <DocShell
      fileName={fileName}
      src={src}
      className={className}
      bare={bare}
      meta={meta}
      actions={<ZoomActions scale={scale} zoom={zoom} reset={reset} />}
    >
      <ScrollerShell
        isolate={!!isolateStyles}
        className="relative min-h-0 flex-1 overflow-hidden bg-card font-mono"
        style={{ fontSize, lineHeight: `${lineHeight}px` }}
      >
        {grammar ? <style>{SYNTAX_STYLE}</style> : null}
        <div
          aria-hidden
          className="pointer-events-none absolute inset-y-0 left-0 z-0 bg-[color-mix(in_oklab,var(--card)_96%,var(--foreground))]"
          style={{ width: gutterWidth }}
        />
        <div
          ref={scrollRef}
          onScroll={handleScroll}
          className="absolute inset-0 overflow-auto"
        >
          <div
            style={{
              height: virtualizer.getTotalSize(),
              width: totalWidth,
              minWidth: "100%",
              position: "relative",
            }}
          >
            {virtualizer.getVirtualItems().map((item) => (
              <div
                key={item.index}
                className="grid"
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  width: "100%",
                  height: lineHeight,
                  transform: `translateY(${item.start}px)`,
                  gridTemplateColumns: `${gutterWidth}px 1fr`,
                }}
              >
                <div
                  className="sticky left-0 z-[1] flex items-center justify-end bg-[color-mix(in_oklab,var(--card)_96%,var(--foreground))] pr-2 text-muted-foreground tabular-nums select-none"
                  style={{ fontSize: Math.round(fontSize * 0.85) }}
                >
                  {item.index + 1}
                </div>
                <div className="flex items-center px-3 whitespace-pre text-foreground">
                  <LineContent
                    line={lines[item.index]}
                    leaves={lineLeaves(lines[item.index])}
                  />
                </div>
              </div>
            ))}
          </div>
        </div>
      </ScrollerShell>
    </DocShell>
  )
}

"use client"

import * as React from "react"
import type * as DOMPurifyNS from "dompurify"

import { abortError, isAbortError, promiseForSignal } from "./file-viewer-async"
import { DocShell, useZoom, ZoomActions } from "./file-viewer-chrome"
import { baseName, timed } from "./file-viewer-core"
import { lruGet, lruSet } from "./file-viewer-resource-cache"
import {
  textResource,
  type TextResourceCache,
  type TextResourceSubscription,
} from "./file-viewer-text-resource"

type Sanitizer = typeof DOMPurifyNS.default
let sanitizerPromise: Promise<Sanitizer> | null = null

function loadSanitizer() {
  if (!sanitizerPromise) {
    sanitizerPromise = import("dompurify").then((m) => {
      const DOMPurify = m.default
      DOMPurify.addHook("afterSanitizeAttributes", (node) => {
        if (node.tagName === "A" && node.getAttribute("href")) {
          node.setAttribute("target", "_blank")
          node.setAttribute("rel", "noopener noreferrer")
        }
      })
      return DOMPurify
    })
  }
  return sanitizerPromise
}

export interface MarkdownHtmlCache {
  load(sub: TextResourceSubscription): Promise<string>
  clear(): void
  size(): number
}

interface MarkdownHtmlEntry {
  html?: Promise<string>
  subscriberPromises: WeakMap<AbortSignal, Promise<string>>
  subscribers: Set<AbortSignal>
}

export function createMarkdownHtmlCache({
  maxEntries = 12,
  textCache = textResource,
}: {
  maxEntries?: number
  textCache?: TextResourceCache
} = {}): MarkdownHtmlCache {
  const entries = new Map<string, MarkdownHtmlEntry>()

  function remove(src: string) {
    entries.delete(src)
  }

  function entryFor(src: string) {
    let entry = lruGet(entries, src)
    if (!entry) {
      entry = {
        subscriberPromises: new WeakMap(),
        subscribers: new Set(),
      }
      lruSet(entries, src, entry, undefined, maxEntries)
    }
    return entry
  }

  function renderHtml(src: string, text: string) {
    return timed(`markdown:render ${baseName(src)}`, () =>
      Promise.all([import("marked"), loadSanitizer()]).then(
        async ([{ marked }, DOMPurify]) => {
          const dirty = String(await marked.parse(text, { gfm: true }))
          return DOMPurify.sanitize(dirty)
        }
      )
    ).catch((error: unknown) => {
      remove(src)
      throw error
    })
  }

  return {
    load({ src, signal }) {
      if (signal.aborted) return Promise.reject(abortError())

      const entry = entryFor(src)

      return promiseForSignal(entry.subscriberPromises, signal, () => {
        entry.subscribers.add(signal)

        return new Promise<string>((resolve, reject) => {
          let done = false

          const cleanup = () => {
            signal.removeEventListener("abort", onAbort)
            entry.subscribers.delete(signal)
          }

          const onAbort = () => {
            if (done) return
            done = true
            cleanup()
            if (!entry.html && entry.subscribers.size === 0) {
              remove(src)
            }
            reject(abortError())
          }

          signal.addEventListener("abort", onAbort, { once: true })

          textCache
            .load({ src, signal })
            .then((text) => {
              if (signal.aborted) throw abortError()
              entry.html ??= renderHtml(src, text)
              return entry.html
            })
            .then(
              (html) => {
                if (done) return
                done = true
                cleanup()
                resolve(html)
              },
              (error: unknown) => {
                if (done) return
                done = true
                cleanup()
                if (!entry.html && !isAbortError(error)) remove(src)
                reject(error)
              }
            )
        })
      })
    },
    clear() {
      entries.clear()
    },
    size() {
      return entries.size
    },
  }
}

export const markdownHtmlCache = createMarkdownHtmlCache()

export function loadMarkdownHtml(
  sub: TextResourceSubscription
): Promise<string> {
  return markdownHtmlCache.load(sub)
}

export function MarkdownDocViewer({
  src,
  fileName,
  className,
  bare,
  descriptorSignal,
}: {
  src: string
  fileName: string
  className?: string
  bare?: boolean
  descriptorSignal: AbortSignal
}) {
  const html = React.use(loadMarkdownHtml({ src, signal: descriptorSignal }))
  const { scale, zoom, reset } = useZoom()
  return (
    <DocShell
      fileName={fileName}
      src={src}
      className={className}
      bare={bare}
      actions={<ZoomActions scale={scale} zoom={zoom} reset={reset} />}
    >
      <style href="fv-markdown" precedence="default">
        {MARKDOWN_STYLE}
      </style>
      <div className="min-h-0 flex-1 overflow-auto bg-card">
        <div
          className="fv-markdown mx-auto max-w-3xl px-6 py-5"
          style={{ zoom: scale }}
          dangerouslySetInnerHTML={{ __html: html }}
        />
      </div>
    </DocShell>
  )
}

